<?php
namespace App\Modules\Canteen\Http\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Canteen\Services\CanteenAccess as Access;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class CatalogController extends Controller {
 public function setup(Request $r){$company=(int)$r->validate(['company_id'=>'required|integer'])['company_id'];Access::requireRole($r,$company,['admin']);DB::transaction(function()use($r,$company){DB::table('communication_companies')->where('id',$company)->lockForUpdate()->first();$count=DB::table('canteen_levels')->where('company_id',$company)->count();abort_if($count,422,'Benefit levels already exist. Edit them instead of resetting.');foreach([50,60,70,80] as $i=>$percent)DB::table('canteen_levels')->insert(['company_id'=>$company,'name'=>'Level '.($i+1),'company_percent'=>$percent,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);foreach(['Drinks','Tea & Coffee','Snacks','Food'] as $name)DB::table('canteen_categories')->insertOrIgnore(['company_id'=>$company,'name'=>$name,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);DB::table('canteen_settings')->insertOrIgnore(['company_id'=>$company,'ordering_enabled'=>false,'timezone'=>'Asia/Karachi','created_at'=>now(),'updated_at'=>now()]);Access::audit($r,$company,'company.initialized',['levels'=>4]);});return response()->json(['message'=>'Four configurable benefit levels and menu categories created. Ordering remains paused.']);}
 public function page(Request $r){if(!$r->user()&&!$r->session()->get('judibas_admin'))return redirect('/login');Access::authorize($r);return app(\App\Http\Controllers\PortalController::class)->index($r,'canteen');}
 public function bootstrap(Request $r){$ids=Access::companies($r);return response()->json(['companies'=>DB::table('communication_companies')->whereIn('id',$ids)->orderBy('name')->get()->map(fn($c)=>['id'=>$c->id,'name'=>$c->name,'role'=>Access::role($r,$c->id)])]);}
 public function index(Request $r){$v=$r->validate(['company_id'=>'required|integer','target_user_id'=>'nullable|integer']);$company=$v['company_id'];$role=Access::role($r,$company);$subjectId=(int)($v['target_user_id']??($r->user()?->id));if(!empty($v['target_user_id']))Access::requireRole($r,$company,['admin','kitchen']);$items=DB::table('canteen_items')->where('company_id',$company)->orderBy('name')->get();$rules=DB::table('canteen_item_rules')->whereIn('item_id',$items->pluck('id'))->get()->groupBy('item_id');foreach($items as $item)$item->rules=$rules->get($item->id,collect());$profiles=collect();if(in_array($role,['admin','kitchen']))$profiles=DB::table('canteen_profiles')->join('users','users.id','=','canteen_profiles.user_id')->where('canteen_profiles.company_id',$company)->whereIn('users.id',DB::table('user_product_access')->where('product_slug','canteen')->select('user_id'))->whereIn('users.id',DB::table('communication_company_memberships')->where('company_id',$company)->select('user_id'))->orderBy('users.name')->get(['canteen_profiles.*','users.name','users.email','users.is_active']);$mine=DB::table('canteen_profiles')->where('company_id',$company)->where('user_id',$subjectId)->first();
  $settings=DB::table('canteen_settings')->where('company_id',$company)->first();$consumption=$mine?\App\Modules\Canteen\Services\Ordering::consumption($company,$mine->user_id,$settings->timezone??'Asia/Karachi'):collect();
  if($mine&&$mine->level_id)foreach($items as $item){$rule=$item->rules->firstWhere('level_id',$mine->level_id);$item->allowance=$rule?['period'=>$rule->period,'limit'=>$rule->quantity_limit,'used'=>(int)($consumption->get($item->id)?->{$rule->period}??0)]:null;}
  return response()->json(['role'=>$role,'settings'=>$settings,'levels'=>DB::table('canteen_levels')->where('company_id',$company)->orderBy('id')->get(),'categories'=>DB::table('canteen_categories')->where('company_id',$company)->orderBy('name')->get(),'items'=>$items,'employees'=>$profiles,'profile'=>$mine]);
 }
 public function save(Request $r,string $resource,?int $id=null){$company=(int)$r->validate(['company_id'=>'required|integer'])['company_id'];Access::requireRole($r,$company,['admin']);abort_unless(in_array($resource,['levels','categories','items','profiles','settings']),404);$table='canteen_'.$resource;if($id)abort_unless(DB::table($table)->where('id',$id)->where('company_id',$company)->exists(),404);
  $rules=match($resource){
   'levels'=>['name'=>['required','string','max:100',Rule::unique($table)->where('company_id',$company)->ignore($id)],'company_percent'=>'required|integer|min:0|max:100','active'=>'required|boolean'],
   'categories'=>['name'=>['required','string','max:100',Rule::unique($table)->where('company_id',$company)->ignore($id)],'active'=>'required|boolean'],
   'items'=>['name'=>'required|string|max:150','category_id'=>['required',Rule::exists('canteen_categories','id')->where('company_id',$company)],'expected_stock_quantity'=>'sometimes|integer|min:0','stock_enabled'=>'required|boolean','stock_quantity'=>'required|integer|min:0|max:10000000','low_stock_threshold'=>'required|integer|min:0|max:10000000','stock_reason'=>'nullable|string|max:250','price'=>'required|numeric|min:0|max:999999.99|decimal:0,2','active'=>'required|boolean','available_from'=>'nullable|date_format:H:i','available_to'=>'nullable|date_format:H:i|after:available_from','rules'=>'present|array|max:100','rules.*.level_id'=>['required','integer','distinct',Rule::exists('canteen_levels','id')->where('company_id',$company)],'rules.*.quantity_limit'=>'nullable|integer|min:0|max:100000','rules.*.period'=>'required|in:day,week,month','rules.*.company_percent'=>'nullable|integer|min:0|max:100'],
   'profiles'=>['level_id'=>['nullable',Rule::exists('canteen_levels','id')->where('company_id',$company)],'eligible'=>'required|boolean'],
   'settings'=>['timezone'=>'sometimes|timezone','within_allowance_mode'=>'required|in:free,level_share','excess_mode'=>'required|in:level_share,full_price,block','ordering_enabled'=>'required|boolean'],
  };$v=$r->validate($rules);abort_if($resource==='profiles'&&!$id,422,'Employees are created and invited through Judibas Administration.');
  DB::transaction(function()use($r,$v,$resource,$table,$company,&$id){$before=$id?DB::table($table)->where('id',$id)->lockForUpdate()->first():null;if($resource==='items'&&$before)$before->rules=DB::table('canteen_item_rules')->where('item_id',$id)->get();$values=$v;unset($values['rules'],$values['stock_reason'],$values['expected_stock_quantity']);if($resource==='items'&&$before&&array_key_exists('expected_stock_quantity',$v)&&$before->stock_quantity!==$v['expected_stock_quantity'])abort(409,'Stock changed while this form was open. Close the form, refresh and try again.');if($resource==='items'&&$before&&(int)$before->stock_quantity!==(int)$v['stock_quantity'])abort_unless(!empty($v['stock_reason']),422,'Give a reason for the stock adjustment.');$values+=['company_id'=>$company,'updated_at'=>now()];if($resource==='settings'){$id=DB::table($table)->where('company_id',$company)->value('id');}if($id)DB::table($table)->where('id',$id)->update($values);else $id=DB::table($table)->insertGetId($values+['created_at'=>now()]);if($resource==='items'){if(!$before||(int)$before->stock_quantity!==(int)$v['stock_quantity'])DB::table('canteen_stock_movements')->insert(['company_id'=>$company,'item_id'=>$id,'quantity_change'=>$v['stock_quantity']-($before->stock_quantity??0),'balance'=>$v['stock_quantity'],'reason'=>$v['stock_reason']??'Opening stock','created_at'=>now()]);DB::table('canteen_item_rules')->where('item_id',$id)->delete();foreach($v['rules'] as $rule)DB::table('canteen_item_rules')->insert(array_intersect_key($rule,array_flip(['level_id','quantity_limit','period','company_percent']))+['item_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);}Access::audit($r,$company,$resource.'.saved',['id'=>$id,'before'=>$before,'after'=>$v]);});return response()->json(['message'=>'Saved.','id'=>$id]);
 }
 public function audit(Request $r){$v=$r->validate(['company_id'=>'required|integer','page'=>'sometimes|integer|min:1']);Access::requireRole($r,$v['company_id'],['admin']);return response()->json(DB::table('canteen_audits')->where('company_id',$v['company_id'])->orderByDesc('id')->paginate(25));}
 public function stock(Request $r){$v=$r->validate(['company_id'=>'required|integer','page'=>'sometimes|integer|min:1']);Access::requireRole($r,$v['company_id'],['admin']);return response()->json(DB::table('canteen_stock_movements')->join('canteen_items','canteen_items.id','=','canteen_stock_movements.item_id')->where('canteen_stock_movements.company_id',$v['company_id'])->orderByDesc('canteen_stock_movements.id')->paginate(25,['canteen_stock_movements.*','canteen_items.name as item_name']));}
}
